//! Small, synchronous wrappers for macOS system identity and entropy services.
//!
//! This crate is scoped to the Apple Silicon macOS 13+ target selected by the
//! workspace. It does not provide implementations for other operating systems.

use std::fmt;
use std::os::fd::BorrowedFd;

#[allow(unsafe_code)]
mod sys;


/// Largest request accepted by [`fill_random`].
pub const MAX_RANDOM_BYTES: usize = 256;

/// Failure reported by a native system service.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SystemError {
    /// The requested random buffer exceeds the wrapper's fixed bound.
    RandomRequestTooLarge { requested: usize, maximum: usize },
    /// `SecRandomCopyBytes` returned a nonzero `OSStatus`.
    RandomStatus(i32),
    /// `getpeereid` failed; this is the `errno` value captured immediately.
    PeerCredentialsErrno(i32),
}

impl fmt::Display for SystemError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::RandomRequestTooLarge { requested, maximum } => {
                write!(f, "random request of {requested} bytes exceeds {maximum}")
            }
            Self::RandomStatus(status) => {
                write!(f, "SecRandomCopyBytes failed with OSStatus {status}")
            }
            Self::PeerCredentialsErrno(errno) => {
                write!(f, "getpeereid failed with errno {errno}")
            }
        }
    }
}

impl std::error::Error for SystemError {}

/// Fill `output` with bytes from Apple's default cryptographic random source.
///
/// Empty output succeeds without calling the native function. Requests above
/// [`MAX_RANDOM_BYTES`] are rejected before any native call. If the native
/// call fails, every byte in `output` is cleared before its status is returned.
pub fn fill_random(output: &mut [u8]) -> Result<(), SystemError> {
    if output.len() > MAX_RANDOM_BYTES {
        return Err(SystemError::RandomRequestTooLarge {
            requested: output.len(),
            maximum: MAX_RANDOM_BYTES,
        });
    }
    if output.is_empty() {
        return Ok(());
    }

    let status = sys::fill_random(output);
    random_result(status, output)
}

fn random_result(status: i32, output: &mut [u8]) -> Result<(), SystemError> {
    if status == 0 {
        Ok(())
    } else {
        output.fill(0);
        Err(SystemError::RandomStatus(status))
    }
}

/// Return the real user ID of the calling process, as reported by `getuid`.
pub fn current_uid() -> u32 {
    sys::current_uid()
}

/// Return the user and group IDs associated with a connected peer socket.
///
/// The descriptor is borrowed only for the duration of this call. Credentials
/// are returned as Darwin's 32-bit `uid_t` and `gid_t` values.
pub fn peer_credentials(socket: BorrowedFd<'_>) -> Result<(u32, u32), SystemError> {
    sys::peer_credentials(socket).map_err(SystemError::PeerCredentialsErrno)
}

#[cfg(test)]
mod tests {
    use super::{random_result, SystemError};

    #[test]
    fn failed_random_status_clears_the_entire_output() {
        let mut output = [0xA5; 8];

        assert_eq!(
            random_result(-42, &mut output),
            Err(SystemError::RandomStatus(-42))
        );
        assert_eq!(output, [0; 8]);
    }

    #[test]
    fn successful_random_status_preserves_native_output() {
        let mut output = [0x3C; 4];

        assert_eq!(random_result(0, &mut output), Ok(()));
        assert_eq!(output, [0x3C; 4]);
    }
}
//! Narrow ABI boundary for macOS system services.
//!
//! The declarations mirror the local macOS SDK: `SecRandomRef` is an opaque
//! pointer, Darwin `uid_t`/`gid_t` are `u32`, and `getpeereid` accepts `int`.

use std::ffi::{c_int, c_void};
use std::os::fd::{AsRawFd, BorrowedFd};

#[link(name = "Security", kind = "framework")]
unsafe extern "C" {
    fn SecRandomCopyBytes(random: *const c_void, count: usize, bytes: *mut c_void) -> c_int;
}

unsafe extern "C" {
    fn getuid() -> u32;
    fn getpeereid(socket: c_int, uid: *mut u32, gid: *mut u32) -> c_int;
    fn __error() -> *mut c_int;
}

/// Call Security synchronously with a bounded, exclusively borrowed output.
pub(super) fn fill_random(output: &mut [u8]) -> i32 {
    debug_assert!(!output.is_empty());
    debug_assert!(output.len() <= super::MAX_RANDOM_BYTES);

    // SAFETY: NULL is Apple's documented default SecRandomRef. The slice
    // pointer is writable for exactly `len()` bytes, `len()` is bounded to 256,
    // and the synchronous API does not retain the pointer, dispatch callbacks,
    // or access it on another thread.
    unsafe {
        SecRandomCopyBytes(
            std::ptr::null(),
            output.len(),
            output.as_mut_ptr().cast::<c_void>(),
        )
    }
}

/// Read the process real user ID using Darwin's `getuid` ABI.
pub(super) fn current_uid() -> u32 {
    // SAFETY: `getuid` takes no pointers and has no preconditions.
    unsafe { getuid() }
}

/// Query the credentials tied to the borrowed descriptor and capture errno.
pub(super) fn peer_credentials(socket: BorrowedFd<'_>) -> Result<(u32, u32), i32> {
    let mut uid = 0_u32;
    let mut gid = 0_u32;
    // SAFETY: `socket` keeps a live descriptor borrowed for this call. The
    // output pointers reference initialized local `u32`s matching Darwin's
    // uid_t/gid_t ABI. getpeereid is synchronous, uses the calling thread, and
    // retains neither pointers nor descriptor after returning.
    let result = unsafe { getpeereid(socket.as_raw_fd(), &mut uid, &mut gid) };
    if result == 0 {
        return Ok((uid, gid));
    }

    // SAFETY: Darwin's `__error` returns this thread's writable errno slot,
    // which is valid to read immediately after a failed system call.
    let errno = unsafe { *__error() };
    Err(errno)
}
use std::fs::File;
use std::os::fd::AsFd;
use std::os::unix::net::UnixStream;

use vexel_platform_macos::{
    current_uid, fill_random, peer_credentials, SystemError, MAX_RANDOM_BYTES,
};

#[test]
fn empty_random_request_succeeds() {
    assert_eq!(fill_random(&mut []), Ok(()));
}

#[test]
fn small_random_request_fills_the_buffer() {
    let mut bytes = [0xA5; 16];

    assert_eq!(fill_random(&mut bytes), Ok(()));
    assert_ne!(bytes, [0xA5; 16]);
}

#[test]
fn maximum_random_request_is_accepted() {
    let mut bytes = [0xA5; MAX_RANDOM_BYTES];

    assert_eq!(fill_random(&mut bytes), Ok(()));
    assert_ne!(bytes, [0xA5; MAX_RANDOM_BYTES]);
}

#[test]
fn random_request_over_the_limit_is_rejected_without_changing_output() {
    let mut bytes = [0xA5; MAX_RANDOM_BYTES + 1];

    assert_eq!(
        fill_random(&mut bytes),
        Err(SystemError::RandomRequestTooLarge {
            requested: MAX_RANDOM_BYTES + 1,
            maximum: MAX_RANDOM_BYTES,
        })
    );
    assert_eq!(bytes, [0xA5; MAX_RANDOM_BYTES + 1]);
}

#[test]
fn connected_unix_socket_reports_the_current_user() {
    let (left, _right) = UnixStream::pair().expect("create local socket pair");

    let (peer_uid, _peer_gid) = peer_credentials(left.as_fd()).expect("read peer credentials");
    assert_eq!(peer_uid, current_uid());
}

#[test]
fn non_socket_descriptor_returns_native_error_classification() {
    let file = File::open("/dev/null").expect("open local null device");

    assert!(matches!(
        peer_credentials(file.as_fd()),
        Err(SystemError::PeerCredentialsErrno(errno)) if errno != 0
    ));
}

